observation.command:
PW=$(od -An -N24 -tx1 /dev/urandom | tr -d ' \n'); BU=qisutu_installer
mariadb -uroot <<SQL
CREATE USER IF NOT EXISTS '${BU}'@'localhost' IDENTIFIED BY '${PW}';
ALTER USER '${BU}'@'localhost' IDENTIFIED BY '${PW}';
GRANT ALL PRIVILEGES ON *.* TO '${BU}'@'localhost' WITH GRANT OPTION;
FLUSH PRIVILEGES;
SQL
cat > /opt/qisutu/var/install/database-bootstrap.conf <<EOF
host=localhost
port=3306
user=${BU}
password=${PW}
EOF
rm -f /opt/qisutu/var/install/session-*.json /opt/qisutu/var/install/installer-operation.lock
chown www-data:www-data /opt/qisutu/var/install/database-bootstrap.conf
chmod 0600 /opt/qisutu/var/install/database-bootstrap.conf
ls -la /opt/qisutu/var/install/; mariadb -u"$BU" -p"$PW" -e "SELECT CURRENT_USER();" 2>&1
